typedef float rational_t;
typedef float time_value_t;
typedef unsigned int message_id_t;

class string_buf;
class stringx
{
protected:
  char *chars;
  string_buf *my_buf;
public:
  stringx(const char *str, int len = -1);
  ~stringx();
};

class widget
{
protected:
  char released_layout[320];
public:
  virtual ~widget();
  virtual void show();
  virtual void hide();
  virtual void ignore_parent();
  virtual void obey_parent();
  virtual void ignore_parent_showing();
  virtual void obey_parent_showing();
  virtual void frame_advance(time_value_t time_inc);
  virtual void render();
  virtual void message_handler(message_id_t message, message_id_t overflow = 0,
                               rational_t parm0 = 0, rational_t parm1 = 0);
  virtual void add_child(widget *child);
  virtual void flush();
  virtual void move_to(short _x, short _y);
  virtual void move_to(time_value_t wt, time_value_t d, short _x, short _y);

  short get_x() const { return *(const short *)(released_layout + 44); }
  short get_y() const { return *(const short *)(released_layout + 46); }
  short get_abs_x() const { return *(const short *)(released_layout + 48); }
  short get_abs_y() const { return *(const short *)(released_layout + 50); }
};

class text_widget : public widget
{
public:
  void set_string(stringx const &_prelocalized_text);
};

class bitmap_widget;

class layout_widget : public widget
{
public:
  layout_widget(const char *_widget_name, widget *_parent, short _x, short _y);
  virtual ~layout_widget() {}
  virtual void frame_advance(time_value_t time_inc);
protected:
  void update_text();
  void update_position(short dx, short dy);
  void update_rotation(short dax, short day, short daz);
  bitmap_widget *bg;
  text_widget *name, *pos, *abs_pos, *x_angle, *y_angle, *z_angle;
  widget *cur_widget;
};

extern "C" int sprintf(char *str, const char *format, ...);

void layout_widget::update_position( short dx, short dy )
{
  if ( cur_widget )
  {
    cur_widget->move_to( cur_widget->get_x() + dx, cur_widget->get_y() + dy );
    char buf[50];
    sprintf( buf, "x %i, y %i", cur_widget->get_x(), cur_widget->get_y() );
    pos->set_string( stringx( buf ) );
    sprintf( buf, "abs x = %i, abs y = %i", cur_widget->get_abs_x(), cur_widget->get_abs_y() );
    abs_pos->set_string( stringx( buf ) );
  }
}
